import { runSync, runMany } from './lib.mjs';
export { runSync, runMany };
export const hx = cp => 'U+' + cp.toString(16).toUpperCase().padStart(4, '0');
export function show(label, r) {
  const L = r.out.split('\n');
  const errLast = r.err ? r.err.trimEnd().split('\n').slice(-1)[0] : '';
  console.log(`${label} rc=${r.rc} L1=${JSON.stringify(L[0])} L2=${JSON.stringify(L[1])} L3=${JSON.stringify(L[2])} L4=${JSON.stringify(L[3])} L5=${JSON.stringify(L[4])} ERR=${JSON.stringify(errLast)}`);
}
export function fmt(r) {
  const L = r.out.split('\n');
  const errLast = r.err ? r.err.trimEnd().split('\n').slice(-1)[0] : '';
  return { rc: r.rc, L: L.slice(0, 5), e: errLast };
}

import { runMany, fmt, hx } from './h.mjs';
// candidate separator-ish codepoints
const cands = [0x2E, 0x3002, 0xFF0E, 0xFF61, 0x2024, 0xFE52, 0xA4F8, 0x1362, 0x0589, 0x06D4,
  0x2E3C, 0xFE12, 0x10FB, 0x3001, 0xFF0F, 0x2F, 0xFF65, 0x30FB, 0x002C, 0x1806];
const doms = [];
const keys = [];
for (const cp of cands) {
  const c = String.fromCodePoint(cp);
  doms.push('a' + c + 'b'); keys.push(hx(cp) + ' a?b');
}
for (const s of ['True', '']) {
  const rs = await runMany(doms, s);
  console.log('=== strict=' + JSON.stringify(s));
  rs.forEach((r, i) => console.log(keys[i], JSON.stringify(fmt(r))));
}

