import { runMany, fmt } from './h.mjs';
const R = (n, c = 'a') => c.repeat(n);
const cases = [
  '', '.', '..', '...', 'a.', '.a', '.a.', 'a..b', 'a...', '..a', 'a.b.', 'a.b..',
  // long labels
  R(63), R(64), R(65),
  R(63) + '.cn', R(64) + '.cn',
  // non-ascii long
  '例'.repeat(63), '例'.repeat(64), '例'.repeat(20), '例'.repeat(21),
  // ascii >63 that is also invalid (starts with hyphen)
  '-' + R(70), R(70) + '-', R(30) + '--' + R(40), 'ab--' + R(70),
  '_' + R(70),
  // hyphen rules
  '-', '--', '---', '----', 'a-', '-a', 'ab--', 'ab--c', 'ab-c', 'a--b', 'xn', 'xn-', 'x-', '-x',
  'a-b', '--a', 'a--', '-ab-',
  // xn-- paths
  'xn--', 'xn---', 'xn--a-', 'xn--!!', 'xn--zzzz', 'xn--a-ecp', 'Xn--FSQ', 'xn--fsq', 'XN--FSQ',
  'xn--0', 'xn--a', 'xn--aa', 'xn--p1ai', 'xn--80adxhks', 'xn--caf-dma', 'xn--cafe-yvc',
  'xn--a-ecp.ru', 'xn--0000', 'xn--tda', 'xn--tdaaa',
  'xn--ls8h', 'xn--bass-3na', 'xn--a-ecp4869e',
];
const res = await runMany(cases, 'True');
const res2 = await runMany(cases, '');
cases.forEach((c, i) => {
  console.log(JSON.stringify(c), '\n  S:', JSON.stringify(fmt(res[i])), '\n  N:', JSON.stringify(fmt(res2[i])));
});

