// runner using --domain=<v> form so leading-hyphen domains work
import { execFile } from 'node:child_process';
export const EXE = '/workspace/dataset/test3_executable';
export const hx = cp => 'U+' + cp.toString(16).toUpperCase().padStart(4, '0');
export function normErr(e) { return (e ?? '').replace(/\[PYI-\d+:ERROR\]/g, '[PYI-N:ERROR]'); }
export async function runMany(domains, strict = 'True', conc = 48) {
  const res = new Array(domains.length);
  let next = 0;
  const worker = async () => {
    for (;;) {
      const i = next++;
      if (i >= domains.length) return;
      res[i] = await new Promise(r => execFile(EXE, ['--domain=' + domains[i], '--strict=' + strict],
        { encoding: 'utf8', maxBuffer: 1 << 26 },
        (e, so, se) => r({ rc: e ? (e.code ?? 1) : 0, out: so, err: normErr(se) })));
    }
  };
  await Promise.all(Array.from({ length: Math.min(conc, domains.length) }, worker));
  return res;
}
export function fmt(r) {
  const L = r.out.split('\n');
  return { rc: r.rc, L: L.slice(0, 5), e: (r.err || '').trim().split('\n').filter(x => x.startsWith('idna.') || x.startsWith('Unicode') || x.includes('Error')).join(' | ') };
}

import { runMany } from './r.mjs';
const cases = [
  '', '.', 'a..b', 'x_y', 'a'.repeat(64), '例'.repeat(64), 'ab--c', 'a-.b', 'x-',
  'xn--', 'xn---', 'xn--!!', 'xn--zzzz', 'xn--a-ecp', 'xn--cafe-yvc', 'xn--a',
  'café', '́abc', 'a‌b', 'a·b', '٠۰',
  'a'.repeat(60) + '.' + 'b'.repeat(60) + '.' + 'c'.repeat(60) + '.' + 'd'.repeat(60),
  '․', '͸', 'aאb', 'א٠۰',
];
const r = await runMany(cases, '');
cases.forEach((c, i) => {
  const frames = (r[i].err || '').split('\n').filter(l => l.includes('line ') || l.includes('Error'));
  console.log(JSON.stringify(c.length > 40 ? c.slice(0, 20) + '...len' + c.length : c), 'rc=' + r[i].rc);
  frames.forEach(f => console.log('   ', f.trim()));
});
